def gen(rng):
    def fmt(g):
        return '%d %d\n' % (len(g), len(g[0])) + '\n'.join(' '.join(map(str, row)) for row in g)
    def rgrid(r, c, hi):
        return [[rng.randint(0, hi) for _ in range(c)] for _ in range(r)]
    tests = [
        fmt([[0]]),
        fmt([[10000]]),
        fmt([[7, 0, 2, 5]]),
        fmt([[3], [1], [4]]),
        fmt([[0, 9, 9], [0, 0, 0]]),
        fmt([[5, 2, 8], [6, 1, 3], [9, 4, 1]]),
    ]
    for _ in range(20):
        r, c = rng.randint(1, 6), rng.randint(1, 6)
        tests.append(fmt(rgrid(r, c, rng.choice([1, 9, 100]))))
    N = 300
    tests.append(fmt(rgrid(N, N, 10000)))
    tests.append(fmt([[10000] * N for _ in range(N)]))
    tests.append(fmt(rgrid(N, N, 1)))
    tests.append(fmt(rgrid(1, N, 10000)))
    tests.append(fmt(rgrid(N, 1, 10000)))
    # a cheap staircase hidden in a field of expensive cells
    g = [[10000] * N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if (i + j) % 2 == 0 and rng.random() < 0.0:
                g[i][j] = 0
    i = j = 0
    g[0][0] = 0
    while i < N - 1 or j < N - 1:
        if i == N - 1:
            j += 1
        elif j == N - 1:
            i += 1
        elif rng.random() < 0.5:
            i += 1
        else:
            j += 1
        g[i][j] = rng.randint(0, 3)
    tests.append(fmt(g))
    return tests
